hunks.patch:
@@ -0,0 +1,6 @@
+@font-face {
+  font-family: "Mx437";
+  src: url("/fonts/mx437.woff2") format("woff2");
+  font-display: swap;
+}
+

@@ -2,10 +8,28 @@
-  color-scheme: light dark;
-  --bg: #f6f6f4;
-  --fg: #1a1a1a;
-  --muted: #7a7a76;
-  --line: #e2e2de;
-  --accent: #1a1a1a;
-  --danger: #c0392b;
-  --sel: #ecece8;
-  --radius: 10px;
-  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
+  color-scheme: dark;
+  /* base16 — hedonicadapter (DOS / sepia) */
+  --base00: #171413;
+  --base01: #2b2420;
+  --base02: #382f29;
+  --base03: #593e2e;
+  --base04: #967b6b;
+  --base05: #d1b5a5;
+  --base06: #e3d2c8;
+  --base07: #ebdfd8;
+  --base08: #94001b;
+  --base09: #a86500;
+  --base0a: #a87e00;
+  --base0b: #277a00;
+  --base0c: #247f94;
+  --base0d: #13578e;
+  --base0e: #790239;
+  --base0f: #a83800;
+
+  --bg: var(--base00);
+  --fg: var(--base05);
+  --muted: var(--base04);
+  --line: var(--base03);
+  --accent: var(--base0d);
+  --danger: var(--base08);
+  --sel: var(--base02);
+  --radius: 1px;
+  font-family: "Mx437", ui-monospace, SFMono-Regular, Menlo, "Cascadia Mono", monospace;

@@ -76 +89 @@
-  outline: 2px solid var(--accent);
+  outline: 1px solid var(--accent);

@@ -92 +105 @@
-  background: color-mix(in srgb, var(--bg) 92%, var(--fg));
+  background: var(--base01);

@@ -214,2 +230,2 @@
-  background: color-mix(in srgb, var(--danger) 14%, transparent);
-  border-radius: 999px;
+  background: color-mix(in srgb, var(--danger) 22%, transparent);
+  border-radius: var(--radius);
